'use strict';
/* Vanilla adaptations of the supplied footer / GlassCalendar references. */
(()=>{
 const icons={calendar:'<rect x="3" y="5" width="18" height="16" rx="4"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',chevron:'<path d="m9 5 7 7-7 7"/>',book:'<path d="M4 4h7v16H4zM13 4h7v16h-7"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',check:'<path d="m5 12 4 4 10-10"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>'};
 const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
 const localDate=s=>{const [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d,12);};
 const noteKey='kienhoc-calendar-notes-v1';let notes=Object.create(null),storageReady=true;
 try{const saved=JSON.parse(localStorage.getItem(noteKey));if(saved?.version===1&&saved.notes&&typeof saved.notes==='object')for(const [k,v] of Object.entries(saved.notes))if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&typeof v==='string'&&v.length<=4000)notes[k]=v;}catch{storageReady=false;}
 let picker,anchor,calendar,selected=key(new Date()),month=localDate(selected),mode='week',draft='',dirty=false,calendarOverflow='';
 const label=d=>new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(d);
 function closePicker(restore=false){if(!picker||picker.hidden)return;picker.hidden=true;anchor?.setAttribute('aria-expanded','false');if(restore&&anchor?.isConnected)anchor.focus();}
 function openPicker(button){if(picker&&!picker.hidden&&anchor===button){closePicker(true);return;}closePicker();anchor=button;if(!picker){picker=document.createElement('div');picker.id='kh-subject-list';picker.className='subject-picker-panel';picker.setAttribute('role','listbox');picker.setAttribute('aria-label','Chọn môn học');document.body.append(picker);}
  const current=typeof currentSubject==='string'?currentSubject:SUBJECTS[0].id;
  picker.innerHTML=`<div class="picker-heading" aria-hidden="true">GÓC HỌC CỦA BẠN<span>Chọn môn để tiếp tục</span></div>${SUBJECTS.map(s=>`<button type="button" role="option" aria-selected="${s.id===current}" tabindex="${s.id===current?0:-1}" data-pick-subject="${s.id}"><span class="picker-code code-${s.id}">${s.code}</span><span><strong>${esc(s.title)}</strong><small>${esc(s.count)}</small></span><span class="picker-check">${s.id===current?icon('check'):''}</span></button>`).join('')}`;
  picker.hidden=false;button.setAttribute('aria-expanded','true');const r=button.getBoundingClientRect(),w=Math.min(370,innerWidth-24);picker.style.width=w+'px';picker.style.left=Math.max(12,Math.min(innerWidth-w-12,r.right-w))+'px';picker.style.maxHeight=Math.max(120,innerHeight-32)+'px';const height=picker.offsetHeight;picker.style.top=Math.max(12,Math.min(r.bottom+10,innerHeight-height-12))+'px';window.KienGlass?.refresh();picker.querySelector('[aria-selected="true"]')?.focus();
 }
 function calendarEnsure(){if(calendar)return;calendar=document.createElement('dialog');calendar.className='calendar-dialog';calendar.setAttribute('aria-labelledby','calendar-title');calendar.innerHTML=`<section class="glass-calendar"><div class="calendar-top"><span class="calendar-eyebrow">MỘT CHÚT CHUẨN BỊ</span><button class="glass-icon-button" data-cal-close aria-label="Đóng lịch">${icon('close')}</button></div><h2 id="calendar-title">Lịch & ghi chú</h2><p class="calendar-intro">Giữ lại điều bạn muốn nhớ, từng ngày.</p><div class="calendar-toolbar"><div class="calendar-modes" role="group" aria-label="Chế độ xem lịch"><button data-cal-mode="week">Tuần</button><button data-cal-mode="month">Tháng</button></div><button class="calendar-today" data-cal-today>Hôm nay</button></div><div class="calendar-month"><h3 id="calendar-month" aria-live="polite"></h3><div><button class="glass-icon-button previous" data-cal-prev aria-label="Khoảng ngày trước">${icon('chevron')}</button><button class="glass-icon-button" data-cal-next aria-label="Khoảng ngày sau">${icon('chevron')}</button></div></div><div class="calendar-weekdays" aria-hidden="true">${['T2','T3','T4','T5','T6','T7','CN'].map(x=>'<span>'+x+'</span>').join('')}</div><div class="calendar-days" role="group" aria-label="Chọn ngày"></div><div class="calendar-note"><label for="calendar-note-text" id="calendar-note-label"></label><textarea id="calendar-note-text" maxlength="4000" placeholder="Ví dụ: Ôn chương 2, xem lại các câu đã đánh dấu…"></textarea><div class="calendar-note-actions"><button data-cal-export class="calendar-export">${icon('download')} Xuất ghi chú</button><button data-cal-save class="calendar-save">Lưu ghi chú ${icon('check')}</button></div><p class="calendar-feedback" role="status" aria-live="polite"></p></div><p class="calendar-storage">Ghi chú lưu riêng trên trình duyệt này, chưa đồng bộ tài khoản. Phần lập kế hoạch sẽ được bổ sung sau.</p></section>`;document.body.append(calendar);
  calendar.addEventListener('close',()=>{document.body.style.overflow=calendarOverflow;});
  calendar.addEventListener('cancel',e=>{e.preventDefault();if(saveNote())calendar.close();});calendar.addEventListener('click',e=>{if(e.target===calendar){const r=calendar.getBoundingClientRect();if((e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)&&saveNote())calendar.close();}});
  calendar.querySelector('textarea').addEventListener('input',e=>{draft=e.target.value;dirty=true;calendar.querySelector('.calendar-feedback').textContent='Chưa lưu · tối đa 4.000 ký tự.';});
 }
 function feedback(t){calendar.querySelector('.calendar-feedback').textContent=t;}
 function saveNote(){if(!dirty)return true;const next={...notes};if(draft.trim())next[selected]=draft;else delete next[selected];if(Object.keys(next).length>1000){feedback('Đã đạt 1.000 ngày ghi chú. Hãy xuất bản sao và dọn ghi chú cũ.');return false;}try{localStorage.setItem(noteKey,JSON.stringify({version:1,notes:next}));notes=next;dirty=false;storageReady=true;feedback('Đã lưu trên trình duyệt này.');updateDays();return true;}catch{feedback('Chưa lưu được. Hãy giữ cửa sổ này mở và xuất bản sao ghi chú.');return false;}}
 function updateDays(){const today=key(new Date()),first=new Date(month.getFullYear(),month.getMonth(),1,12),last=new Date(month.getFullYear(),month.getMonth()+1,0,12);let dates=[],padding=0;if(mode==='month'){padding=(first.getDay()+6)%7;for(let d=1;d<=last.getDate();d++)dates.push(new Date(first.getFullYear(),first.getMonth(),d,12));}else{const start=localDate(selected);start.setDate(start.getDate()-(start.getDay()+6)%7);for(let i=0;i<7;i++){const d=new Date(start);d.setDate(d.getDate()+i);dates.push(d);}}
  calendar.querySelector('.calendar-days').innerHTML='<span aria-hidden="true"></span>'.repeat(padding)+dates.map(d=>{const k=key(d);return `<button data-cal-date="${k}" aria-label="${esc(label(d))}${notes[k]?', có ghi chú':''}" aria-pressed="${k===selected}" ${k===today?'aria-current="date"':''} class="${notes[k]?'has-note':''}">${d.getDate()}</button>`;}).join('');
 }
 function calendarRender(){const date=localDate(selected);calendar.querySelector('#calendar-month').textContent=new Intl.DateTimeFormat('vi-VN',{month:'long',year:'numeric'}).format(mode==='month'?month:date);calendar.querySelectorAll('[data-cal-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.calMode===mode)));calendar.querySelector('#calendar-note-label').textContent=label(date);draft=notes[selected]||'';dirty=false;calendar.querySelector('textarea').value=draft;feedback(storageReady?'Chọn ngày rồi viết điều bạn muốn ghi nhớ.':'Không đọc được dữ liệu đã lưu. Hãy kiểm tra quyền lưu trữ của trình duyệt.');updateDays();window.KienGlass?.refresh();}
 function openCalendar(){closePicker();calendarEnsure();if(calendar.open)return;document.querySelector('dialog[open]')?.close();calendarRender();calendarOverflow=document.body.style.overflow;document.body.style.overflow='hidden';calendar.showModal();window.KienGlass?.refresh();calendar.querySelector('[data-cal-close]').focus();}
 function exportNotes(){const out={...notes};if(dirty){if(draft.trim())out[selected]=draft;else delete out[selected];}const blob=new Blob([JSON.stringify({version:1,notes:out},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='kienhoc-ghi-chu-'+key(new Date())+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);feedback('Đã tạo bản sao gồm cả nội dung đang viết.');}
 function footer(){const f=document.querySelector('footer');if(!f)return;f.innerHTML=`<div class="kh-footer"><div class="footer-main"><div class="footer-brand"><span class="footer-monogram">K</span><div><strong>Kiến Học</strong><p>Học có hướng, nhớ có cách.</p></div></div><p class="footer-description">Một góc học tập được xây dựng từ sự tò mò,<br>và mong muốn cùng nhau tiến bộ.</p><div class="footer-authors"><span>ĐƯỢC XÂY DỰNG BỞI</span><strong>Dũng Phạm <i>&</i> Viết Kiên</strong><small>Cùng đóng góp và phát triển Kiến Học.</small></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Kiến Học</span><nav aria-label="Liên kết cuối trang"><button data-catalog>Thư viện môn học</button><button data-open-calendar>Lịch & ghi chú</button><button data-appearance>Giao diện</button></nav><span class="footer-contact">Thông tin liên hệ sẽ được cập nhật.</span></div></div>`;}
 function refresh(){closePicker();footer();const label=typeof subjectTitle==='function'?subjectTitle():SUBJECTS[0].title;const header=document.querySelector('.subject-switch');if(header){header.outerHTML=`<button type="button" class="subject-picker-trigger" aria-label="Đổi môn học" aria-haspopup="listbox" aria-expanded="false" aria-controls="kh-subject-list" data-open-subject-picker>${icon('book')}<span>${esc(label)}</span><span class="picker-chevron">${icon('chevron')}</span></button>`;}
  for(const target of document.querySelectorAll('.header-actions,.mobile-topbar'))if(!target.querySelector('[data-open-calendar]')){const b=document.createElement('button');b.className='calendar-trigger';b.dataset.openCalendar='';b.setAttribute('aria-label','Mở lịch và ghi chú');b.innerHTML=icon('calendar')+'<span>Lịch & ghi chú</span>';target.insertBefore(b,target.querySelector('.auth-trigger-wrap,#mobile-auth-btn'));}
  const mobile=document.querySelector('.mobile-topbar');if(mobile&&!mobile.querySelector('[data-open-subject-picker]')){const b=document.createElement('button');b.className='mobile-subject-trigger';b.dataset.openSubjectPicker='';b.setAttribute('aria-label','Đổi môn học');b.setAttribute('aria-haspopup','listbox');b.setAttribute('aria-expanded','false');b.setAttribute('aria-controls','kh-subject-list');b.innerHTML=icon('book');mobile.insertBefore(b,mobile.querySelector('[data-open-calendar]'));}window.KienGlass?.refresh();
 }
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!e.target.closest('.subject-picker-panel,[data-open-subject-picker]'))closePicker();if(!b||b.disabled)return;if(b.hasAttribute('data-open-subject-picker'))openPicker(b);else if(b.dataset.pickSubject){const id=b.dataset.pickSubject;closePicker();openSubject(id);[...document.querySelectorAll('[data-open-subject-picker]')].find(el=>el.offsetParent!==null)?.focus();}else if(b.hasAttribute('data-open-calendar'))openCalendar();else if(b.hasAttribute('data-cal-close')){if(saveNote())calendar.close();}else if(b.hasAttribute('data-cal-save'))saveNote();else if(b.hasAttribute('data-cal-export'))exportNotes();else if(b.dataset.calDate){if(saveNote()){selected=b.dataset.calDate;month=localDate(selected);calendarRender();calendar.querySelector(`[data-cal-date="${selected}"]`)?.focus();}}else if(b.dataset.calMode){if(saveNote()){mode=b.dataset.calMode;month=localDate(selected);calendarRender();}}else if(b.hasAttribute('data-cal-today')){if(saveNote()){selected=key(new Date());month=localDate(selected);calendarRender();}}else if(b.hasAttribute('data-cal-prev')||b.hasAttribute('data-cal-next')){if(!saveNote())return;const delta=b.hasAttribute('data-cal-prev')?-1:1;if(mode==='month')month=new Date(month.getFullYear(),month.getMonth()+delta,1,12);else{const d=localDate(selected);d.setDate(d.getDate()+delta*7);selected=key(d);month=d;}calendarRender();}});
 document.addEventListener('keydown',e=>{if(picker&&!picker.hidden){if(e.key==='Escape'){e.preventDefault();closePicker(true);}else if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const options=[...picker.querySelectorAll('[role="option"]')],i=options.indexOf(document.activeElement),next=e.key==='Home'?0:e.key==='End'?options.length-1:(i+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((b,j)=>b.tabIndex=j===next?0:-1);options[next].focus();}else if(e.key==='Tab')closePicker();}else if(e.target.closest('[data-open-subject-picker]')&&['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();openPicker(e.target.closest('button'));}});
 window.addEventListener('resize',()=>closePicker());window.addEventListener('scroll',e=>{if(!picker?.contains(e.target))closePicker();},true);
 window.addEventListener('pagehide',()=>{if(calendar?.open&&dirty)saveNote();});
 window.KienWorkspace={refresh};
})();
